function taskRows(limit){return app.tasks.slice(0,limit||app.tasks.length).map(function(t,i){return '<div class="task-line '+(t[2]==='已完成'?'done':'')+'"><label><input type="checkbox" data-task="'+i+'" '+(t[2]==='已完成'?'checked':'')+'><span>'+t[0]+'</span></label><span class="tag '+(t[1]==='高'?'high':t[1]==='中'?'medium':'low')+'">'+t[1]+'</span><span class="task-due">'+t[3]+'</span></div>'}).join('')}
function head(title,sub,action){return '<div class="page-heading"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+(action||'')+'</div>'}
function dashboard(){return '<div class="eyebrow"><span></span>2024 年 12 月 7 日 · 星期六</div><div class="welcome-row"><div><h1>下午好，Alex</h1><p>今天账号整体表现稳定，有 <b>2 个事项</b>值得关注。</p></div><button class="date-button">▣ 2024.12.01 - 2024.12.07⌄</button></div><button class="insight-banner" id="banner"><span class="insight-badge">▥</span><span><b>AI 运营总监洞察</b><p>过去 7 天，你的账号增长 <strong>22%</strong>，主要来自教程型内容。建议继续发布同类内容，同时优化低互动笔记。</p></span><span class="insight-link">查看详情 <span>›</span></span></button>'+metricCards(metrics)+'<div class="grid-main"><section class="card"><div class="card-heading"><h2>⌁ 数据趋势</h2><button class="text-button" data-nav="analytics">查看完整分析 ›</button></div><div class="chart-controls"><div class="tabs"><button class="active">曝光量</button><button>互动量</button><button>粉丝数</button></div><div class="segment"><button class="active">7天</button><button>30天</button><button>90天</button></div></div>'+chart()+'<div class="chart-footnote"><i></i>曝光量 <b>128,400</b> · 较上周期 +23.1%</div></section><section class="card"><div class="card-heading"><h2>AI 今日洞察</h2><button class="text-button" id="all-insights">查看全部 ›</button></div><div class="insights-list">'+[['↗','增长机会'],['△','需要关注'],['♧','内容建议'],['✓','内容优化建议']].map(function(x,i){return '<button class="insight-row" data-insight="'+i+'"><span class="tile-icon">'+x[0]+'</span><span><b>'+x[1]+'</b><p>'+insights[i].slice(0,22)+'…</p></span><span class="row-arrow">›</span></button>'}).join('')+'</div></section></div><div class="bottom-grid"><section class="card"><div class="card-heading"><h2>近期内容表现</h2><button class="text-button" data-nav="content">查看全部 ›</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>内容标题</th><th>发布时间</th><th class="n">曝光量</th><th class="n">互动率</th></tr></thead><tbody>'+tableRows()+'</tbody></table></div></section><section class="card"><div class="card-heading"><h2>今日任务</h2><button class="text-button" data-nav="tasks">查看全部 ›</button></div><div class="task-summary"><div><b>5</b><span>待完成</span></div><div><b>2</b><span>进行中</span></div><div><b style="color:var(--green)">8</b><span>已完成</span></div></div><div class="task-checklist">'+taskRows(4)+'</div></section></div>'}
function analytics(){return head('数据分析','从多个维度了解你的小红书账号表现，发现增长机会。','<button class="date-button">▣ 2024.12.01 - 2024.12.07⌄</button>')+'<div class="page-tabs"><button class="active">整体概览</button><button>内容分析</button><button>粉丝分析</button><button>互动分析</button></div>'+metricCards(metrics.slice(1,5))+'<section class="card large-chart"><div class="card-heading"><h2>⌁ 趋势分析</h2><div class="segment"><button class="active">7天</button><button>30天</button><button>90天</button></div></div>'+chart()+'</section><section class="card"><div class="card-heading"><h2>内容排行榜</h2><button class="text-button" data-nav="content">查看全部 ›</button></div><div class="tabs" style="margin-bottom:13px"><button class="active">按曝光量</button><button>按互动量</button><button>按收藏数</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>#</th><th>内容标题</th><th>分类</th><th>发布时间</th><th class="n">曝光量</th><th class="n">互动率</th></tr></thead><tbody>'+app.notes.map(function(n,i){return '<tr><td style="color:'+(i===0?'var(--red)':'var(--weak)')+'">'+(i+1)+'</td><td><div class="content-title">'+cover(i)+'<button class="table-title-link">'+n[0]+'</button></div></td><td>'+n[1]+'</td><td>'+n[2]+'</td><td class="n">'+n[3]+'</td><td class="n">'+n[4]+'</td></tr>'}).join('')+'</tbody></table></div></section>'}
function content(){return head('内容管理','管理你的所有笔记，查看数据表现，优化内容策略。','<button class="primary" id="new-note">＋ 发布笔记</button>')+'<section class="card"><div class="toolbar"><select class="filter"><option>全部分类</option><option>职场</option><option>效率工具</option><option>运营经验</option><option>生活</option></select><select class="filter"><option>全部状态</option><option>已发布</option><option>草稿</option></select><input class="table-search" placeholder="⌕  搜索笔记标题…" /></div><div class="table-scroll"><table class="data-table"><thead><tr><th>#</th><th>内容标题</th><th>分类</th><th>发布时间</th><th>状态</th><th class="n">曝光量</th><th class="n">互动率</th></tr></thead><tbody>'+app.notes.map(function(n,i){return '<tr><td>'+(i+1)+'</td><td><div class="content-title">'+cover(i)+'<button class="table-title-link" data-note="'+i+'">'+n[0]+'</button></div></td><td>'+n[1]+'</td><td>'+n[2]+'</td><td><span class="tag '+(n[3]==='草稿'?'gray':'green')+'">'+n[3]+'</span></td><td class="n">'+n[3]+'</td><td class="n">'+n[4]+'</td></tr>'}).join('')+'</tbody></table></div><div class="table-footer"><span>共 '+app.notes.length+' 条内容</span><span>‹　 <b style="color:var(--red)">1</b>　2　3　4　…　›</span></div></section>'}
function tasks(){return head('任务中心','将 AI 建议转化为可执行任务，持续推动账号增长。','<button class="primary" id="new-task">＋ 创建任务</button>')+'<div class="metrics-grid four">'+[['任务总数',app.tasks.length,'var(--ink)'],['待完成',app.tasks.filter(function(t){return t[2]==='待完成'}).length,'var(--red)'],['进行中',app.tasks.filter(function(t){return t[2]==='进行中'}).length,'var(--blue)'],['已完成',app.tasks.filter(function(t){return t[2]==='已完成'}).length,'var(--green)']].map(function(x){return '<article class="metric-card"><div class="metric-number" style="color:'+x[2]+'">'+x[1]+'</div><div class="metric-top">'+x[0]+'</div></article>'}).join('')+'</div><section class="card"><div class="toolbar"><select class="filter"><option>全部状态</option><option>待完成</option><option>进行中</option><option>已完成</option></select><select class="filter"><option>全部优先级</option><option>高</option><option>中</option><option>低</option></select><select class="filter"><option>全部来源</option><option>AI 推荐</option><option>手动创建</option></select><input class="table-search" placeholder="⌕  搜索任务…" /></div><div class="table-scroll"><table class="data-table"><thead><tr><th>任务标题</th><th>优先级</th><th>状态</th><th>截止时间</th><th>来源</th></tr></thead><tbody>'+app.tasks.map(function(t,i){return '<tr><td><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" data-task="'+i+'" '+(t[2]==='已完成'?'checked':'')+'><span>'+t[0]+'</span></label></td><td><span class="tag '+(t[1]==='高'?'high':t[1]==='中'?'medium':'low')+'">'+t[1]+'</span></td><td><span class="tag '+(t[2]==='进行中'?'gray':t[2]==='待完成'?'medium':'green')+'">'+t[2]+'</span></td><td>'+t[3]+'</td><td>'+t[4]+'</td></tr>'}).join('')+'</tbody></table></div></section>'}
function settings(){return head('账号设置','管理账号信息、AI 偏好与通知设置.')+'<div class="page-tabs"><button class="active">账号信息</button><button>AI 偏好</button><button>通知设置</button></div><div class="settings-grid"><section class="card"><div class="profile-heading"><span class="avatar">A</span><span><b>Alex的成长笔记</b><small>个人创作者 · 已连接</small></span></div><label class="field">小红书账号名称<input value="Alex的成长笔记"/></label><label class="field">小红书账号 ID<input value="xhs_demo_001"/></label><label class="field">个人简介<textarea>分享个人成长、效率工具和生活方式</textarea></label><button class="primary" id="save-settings">保存修改</button></section><section class="preview-card"><div class="preview-cover"><span class="vase"></span><span class="book"></span></div><div class="preview-body"><div class="preview-user"><span class="avatar">A</span><span><b>Alex的成长笔记</b><small>Alex · 个人创作者</small></span></div><div class="preview-stats"><span><b>2,846</b><small>粉丝</small></span><span><b>128,400</b><small>获赞与收藏</small></span><span><b>8.7%</b><small>互动率</small></span></div><p class="preview-bio">分享个人成长、效率工具和生活方式</p><button class="primary full">关注</button></div></section></div>'}
function ideas(){const a=[['趋势机会','教程型内容','最近表现高于平均 34%，适合继续扩展“从 0 到 1”系列。'],['评论灵感','运营经验','把评论区高频问题整理成一篇清单，增强收藏价值。'],['生活方式','效率工具','把你的效率工具融入真实场景，做一组连续内容。'],['个人 IP','失败复盘','用一个具体的失败案例开启下一篇复盘。'],['增长实验','封面测试','测试 3 种不同封面信息密度，记录点击变化。'],['待完善','读书笔记','把最近的读书笔记拆成 5 个可执行方法。']];return head('灵感库','保存、整理和拓展下一篇内容的灵感。','<button class="primary" id="new-idea">＋ 新建灵感</button>')+'<div class="idea-grid">'+a.map(function(x,i){return '<article class="idea-card"><span class="tag '+(i===0?'high':i===1?'medium':i===5?'gray':'green')+'">'+(i===0?'上升':i===1?'值得尝试':'可连载')+'</span><h3>'+x[0]+' · '+x[1]+'</h3><p>'+x[2]+'</p><button class="text-button" data-idea="'+i+'">查看详情　›</button></article>'}).join('')+'</div>'}
function render(){document.querySelector('#nav').innerHTML=navHtml();document.querySelector('#main').innerHTML=app.view==='dashboard'?dashboard():app.view==='analytics'?analytics():app.view==='content'?content():app.view==='tasks'?tasks():app.view==='settings'?settings():ideas();bind()}
function bind(){ $$('#nav .nav-item').forEach(function(b){b.onclick=function(){go(b.dataset.view)}});$$('[data-nav]').forEach(function(b){b.onclick=function(){go(b.dataset.nav)}});$$('[data-task]').forEach(function(c){c.onchange=function(){app.tasks[+c.dataset.task][2]=c.checked?'已完成':'待完成';toast(c.checked?'任务已完成':'任务已移回待完成');render()}});$$('.insight-row').forEach(function(b){b.onclick=function(){openAI(insights[+b.dataset.insight])}});$('#banner')?.addEventListener('click',function(){openAI(insights[0])});$('#all-insights')?.addEventListener('click',function(){openAI()});$('#new-task')?.addEventListener('click',function(){taskDialog()});$('#new-note')?.addEventListener('click',function(){noteDialog()});$('#new-idea')?.addEventListener('click',function(){ideaDialog()});$('#save-settings')?.addEventListener('click',function(){toast('账号信息已保存')});$$('[data-note]').forEach(function(b){b.onclick=function(){noteDialog(app.notes[+b.dataset.note])}});$$('[data-idea]').forEach(function(b){b.onclick=function(){ideaDialog(+b.dataset.idea)}})}
function go(v){app.view=v;render();document.querySelector('#main').focus()}
