function closeAI(){$('#ai-panel').hidden=true;$('.ai-fab').style.display='flex'}
function intro(){return '<div class="chat-intro"><div class="ai-logo">✦</div><h3>你好，Alex 👋</h3><p>我已经分析了你最近的账号表现。<br/>你可以直接问我运营相关的问题。</p><span class="quick-label">试试这样问</span><div class="quick-questions">'+['为什么最近流量下降？','分析最近 7 天的数据','我今天应该做什么？','哪些内容值得继续做？'].map(function(x){return '<button data-question="'+x+'"><span>↗</span>'+x+'<b style="margin-left:auto;color:var(--weak)">›</b></button>'}).join('')+'</div></div>'}
function appendBot(text){$('#chat').insertAdjacentHTML('beforeend','<div class="chat-message bot"><div class="message-label"><span class="ai-logo">✦</span><span>AI 运营总监</span></div><div class="reply"><p>'+text+'</p><div class="ai-action"><small>建议行动</small><h4>发布教程型内容</h4><span class="tag high">高优先级</span><button class="primary" data-ai-task>＋ 创建任务</button></div></div></div>');$$('[data-ai-task]').forEach(function(b){b.onclick=function(){taskDialog('发布教程型内容')}});$('#chat').scrollTop=$('#chat').scrollHeight}
function send(text){if(!text||!text.trim())return;$('#chat').innerHTML+='<div class="chat-message user"><p>'+text+'</p></div>';$('#chat-input').value='';setTimeout(function(){appendBot('根据最近 7 天数据，教程型内容仍是最稳定的增长来源。建议本周继续发布 2 篇，并在结尾加入一个具体提问，引导评论。')},350)}
function taskDialog(prefill){const d=$('#dialog');$('#dialog-body').innerHTML='<div class="dialog-header"><h2>创建任务</h2><button class="icon-button" data-close>×</button></div><p class="dialog-sub">把 AI 建议或你的想法变成下一步行动。</p><label class="field">任务标题<input id="d-title" value="'+(prefill||'')+'"/></label><div class="field-row"><label class="field">优先级<select id="d-priority"><option>高</option><option>中</option><option>低</option></select></label><label class="field">截止日期<select id="d-due"><option>今天</option><option>明天</option><option>3天内</option></select></label></div><div class="dialog-actions"><button class="secondary" data-close>取消</button><button class="primary" id="save-task">创建任务</button></div>';d.showModal();$$('[data-close]').forEach(function(b){b.onclick=function(){d.close()}});$('#save-task').onclick=function(){app.tasks.unshift([$('#d-title').value||'未命名任务',$('#d-priority').value,'待完成',$('#d-due').value]);d.close();toast('任务已创建');go('tasks')}}
function noteDialog(n){const d=$('#dialog');$('#dialog-body').innerHTML='<div class="dialog-header"><h2>'+(n?n[0]:'发布新笔记')+'</h2><button class="icon-button" data-close>×</button></div><p class="dialog-sub">'+(n?'这篇内容最近 7 天的数据表现：':'创建内容后，你可以继续在内容管理中编辑。')+'</p>'+(n?'<div class="dialog-result"><p><b>曝光量</b>　'+n[3]+'　　<b>互动率</b>　'+n[4]+'</p><p><b>AI 建议</b>　把标题中的结果前置，首图减少装饰信息。</p></div>':'<label class="field">笔记标题<input placeholder="例如：我用 3 个方法提升内容质量"/></label>')+'<div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>';d.showModal();$$('[data-close]').forEach(function(b){b.onclick=function(){d.close()}})}
function ideaDialog(i){const d=$('#dialog');$('#dialog-body').innerHTML='<div class="dialog-header"><h2>保存灵感</h2><button class="icon-button" data-close>×</button></div><p class="dialog-sub">灵感会保存在灵感库中，随时可以转成任务。</p><label class="field">灵感标题<input value="'+(i===undefined?'':['教程型内容','运营经验','效率工具','失败复盘','封面测试','读书笔记'][i])+'"/></label><label class="field">补充描述<textarea placeholder="写下你的切入角度…"></textarea></label><div class="dialog-actions"><button class="secondary" data-close>取消</button><button class="primary" id="save-idea">保存灵感</button></div>';d.showModal();$$('[data-close]').forEach(function(b){b.onclick=function(){d.close()}});$('#save-idea').onclick=function(){d.close();toast('灵感已保存')}}
function searchDialog(){const d=$('#dialog');$('#dialog-body').innerHTML='<div class="dialog-header"><h2>快速搜索</h2><button class="icon-button" data-close>×</button></div><input class="table-search" style="width:100%;height:39px;margin:4px 0 12px" placeholder="搜索页面、笔记或任务…"/><button class="search-result" data-go="dashboard">运营总览<small>页面</small></button><button class="search-result" data-go="tasks">发布一篇知识型内容<small>任务 · 今天</small></button><button class="search-result" data-go="content">冬日氛围感日常<small>内容 · 32,400 曝光</small></button>';d.showModal();$$('[data-close]').forEach(function(b){b.onclick=function(){d.close()}});$$('[data-go]').forEach(function(b){b.onclick=function(){d.close();go(b.dataset.go)}})}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(window.__t);window.__t=setTimeout(function(){t.classList.remove('visible')},2200)}
$('#nav').innerHTML=navHtml();$('#chat').innerHTML=intro();bind();$('#ai-fab').onclick=openAI;$('#close-ai').onclick=closeAI;$('#new-chat').onclick=function(){$('#chat').innerHTML=intro();bind()};$('#upgrade').onclick=openAI;$('#header-avatar').onclick=function(){go('settings')};$('#user-account').onclick=function(){go('settings')};$('#chat-form').onsubmit=function(e){e.preventDefault();send($('#chat-input').value)};$('#chat').addEventListener('click',function(e){if(e.target.dataset.question)send(e.target.dataset.question)});$('#global-search').onclick=searchDialog;$('#notifications').onclick=function(){toast('暂无新的通知')};render();

/* Product polish layer: shared interactions stay outside page templates so new screens inherit them. */
(function(){
  var storageKey='ai-growth-os-demo-state';
  function persist(){try{localStorage.setItem(storageKey,JSON.stringify({tasks:app.tasks}))}catch(e){}}
  function restore(){try{var saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&Array.isArray(saved.tasks)){app.tasks=saved.tasks}}catch(e){}}
  restore();
  function markActive(buttons,target){buttons.forEach(function(b){b.classList.toggle('active',b===target)})}
  function filterRows(input){var value=(input.value||'').trim().toLowerCase();var table=input.closest('.card');if(!table)return;table.querySelectorAll('tbody tr').forEach(function(row){row.hidden=!!value&&row.textContent.toLowerCase().indexOf(value)<0})}
  function statusFilter(select){var card=select.closest('.card');if(!card)return;var value=select.value;card.querySelectorAll('tbody tr').forEach(function(row){row.hidden=value!=='全部状态'&&row.textContent.indexOf(value)<0})}
  document.addEventListener('keydown',function(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog()}if(e.key==='/'&&document.activeElement.tagName!=='INPUT'&&document.activeElement.tagName!=='TEXTAREA'){e.preventDefault();searchDialog()}if(e.key==='Escape'&&$('#ai-panel')&&!$('#ai-panel').hidden)closeAI()});
  document.addEventListener('input',function(e){if(e.target.classList.contains('table-search'))filterRows(e.target)});
  document.addEventListener('change',function(e){if(e.target.matches('.filter'))statusFilter(e.target)});
  document.addEventListener('click',function(e){
    var tab=e.target.closest('.tabs button,.segment button,.page-tabs button');
    if(tab){var group=tab.parentElement.querySelectorAll('button');markActive(Array.from(group),tab);if(tab.closest('.segment'))toast('已切换到 '+tab.textContent.trim()+' 数据');if(tab.closest('.page-tabs'))toast('已切换到 '+tab.textContent.trim());}
    var nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();go(nav.dataset.nav)}
    var check=e.target.closest('[data-task]');if(check){setTimeout(persist,0)}
  });
  var oldToast=toast;window.toast=function(message){oldToast(message)};
  var oldTaskDialog=taskDialog;window.taskDialog=function(prefill){oldTaskDialog(prefill);setTimeout(function(){var save=$('#save-task');if(save)save.addEventListener('click',persist,{once:true})},0)};
  /* Keep the visible task total honest when the user checks an item from the dashboard. */
  var oldGo=go;window.go=function(view){oldGo(view);if(view==='tasks'){var all=$('.metrics-grid.four');if(all){var labels=all.querySelectorAll('.metric-number');if(labels[0])labels[0].textContent=app.tasks.length;if(labels[1])labels[1].textContent=app.tasks.filter(function(t){return t[2]==='待完成'}).length;}}};
  persist();
})();

(function(){
  function applyTableFilters(card){
    if(!card)return;
    var selects=Array.from(card.querySelectorAll('.filter'));
    var search=(card.querySelector('.table-search')?.value||'').trim().toLowerCase();
    var rows=Array.from(card.querySelectorAll('tbody tr'));
    rows.forEach(function(row){
      var text=row.textContent.toLowerCase(), ok=!search||text.indexOf(search)>=0;
      selects.forEach(function(sel,i){
        var val=sel.value;
        var ignored=val.indexOf('全部')===0;
        if(!ignored&&i===0)ok=ok&&text.indexOf(val.toLowerCase())>=0;
        if(!ignored&&i>0)ok=ok&&text.indexOf(val.toLowerCase())>=0;
      });
      row.hidden=!ok;
    });
    var footer=card.querySelector('.table-footer span');
    if(footer)footer.textContent='显示 '+rows.filter(function(r){return !r.hidden}).length+' 条';
  }
  document.addEventListener('change',function(e){if(e.target.classList.contains('filter'))applyTableFilters(e.target.closest('.card'))});
  document.addEventListener('input',function(e){if(e.target.classList.contains('table-search'))applyTableFilters(e.target.closest('.card'))});
  document.addEventListener('click',function(e){
    var period=e.target.closest('.segment button');
    if(period){var parent=period.closest('.card');if(parent){parent.dataset.period=period.textContent.trim();var note=parent.querySelector('.chart-footnote');if(note)note.innerHTML='<i></i>'+period.textContent.trim()+' 视图 · 数据已更新';}}
  });
  /* Restore task edits before first paint, so a refresh keeps the user's work. */
  try{var saved=JSON.parse(localStorage.getItem('ai-growth-os-demo-state')||'null');if(saved&&Array.isArray(saved.tasks)){app.tasks=saved.tasks;render()}}catch(e){}
})();
